import * as s from "../../core/validation/index.js";
import type { Schema } from "../../core/validation/schema.js";
import { finishReason2Schema, type FinishReason2 } from "../finish-reason2.js";

/**
 * Termination condition of the generation. `stop` means the API returned the full chat completions
 * generated by the model without running into any limits. `length` means the generation exceeded
 * `max_tokens` or the conversation exceeded the max context length. `tool_calls` means the API has
 * generated tool calls.
 */
export type FinishReason21 = FinishReason2;

export const finishReason21Schema: Schema<FinishReason21> = s.of<FinishReason21>(
  s.union([s.lazy(() => finishReason2Schema)]),
);
